usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Embeddings.New(
		context.TODO(),
		openai.EmbeddingNewParams{
			Input: "string",
			Model: "string",
			EncodingFormat: openai.CreateEmbeddingRequestEncodingFormatFloat,
			Dimensions: param.NewOpt[int64](1),
			User: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
